#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.UI.Addons
{
    public class AddonsUI : MonoBehaviour
    {
        public void SetIndexVisible(bool visible)
        {
            indexUI.SetActive(visible);
        }
        public void SetLoadingVisible(bool visible)
        {
            loadingScreen.SetActive(visible);
        }
        public void SetLoadingProgress(float progress, string text)
        {
            loadingProgress.SetValueWithoutNotify(progress);
            loadingProgressText.text = text;
        }
        private void Awake()
        {
            buttonDict.Add(Buttons.LanguagePack, languagePackButton);
            buttonDict.Add(Buttons.Return, returnButton);

            foreach (var pair in buttonDict)
            {
                pair.Value.onClick.AddListener(() => OnButtonClick?.Invoke(pair.Key));
            }
        }
        public event Action<Buttons>? OnButtonClick;
        [SerializeField]
        private Button languagePackButton = null!;
        [SerializeField]
        private Button returnButton = null!;
        [SerializeField]
        private GameObject indexUI = null!;
        [SerializeField]
        private GameObject loadingScreen = null!;
        [SerializeField]
        private Slider loadingProgress = null!;
        [SerializeField]
        private TextMeshProUGUI loadingProgressText = null!;
        private Dictionary<Buttons, Button> buttonDict = new Dictionary<Buttons, Button>();

        public enum Buttons
        {
            LanguagePack,
            Return
        }
    }
}
